m=0.23;
M=2.4;
l=0.36;
g=-9.81;
d=4.4;
%ref=[1;0;pi;0];
t_sim=0:0.001:30;
x0=[0;0;pi/3+0.1;0];
u = 0;
%%
[t,x]=ode45(@(t,x)CtP(x,M,m,l,g,0,d),t_sim,x0);
%%

figure; %[output:2feee169]
hold on; %[output:2feee169]
subplot(2,2,1); %[output:2feee169]
plot(t,rad2deg(x(:,3)),'blue') %[output:2feee169]
ylabel("theta") %[output:2feee169]

subplot(2,2,2); %[output:2feee169]
plot(t,rad2deg(x(:,4)),'blue') %[output:2feee169]
ylabel("thetaDot") %[output:2feee169]

subplot(2,2,3); %[output:2feee169]
plot(t,x(:,1),'blue') %[output:2feee169]
ylabel("x") %[output:2feee169]

subplot(2,2,4); %[output:2feee169]
plot(t,x(:,2),'blue') %[output:2feee169]
ylabel("xDot") %[output:2feee169]
hold off; %[output:2feee169]
%%
%% CTP
function dx = CtP(x, M, m, l, g, u, b)
    % CtP: cart-pendulum dynamics (point mass at end of rod)
    % states: x(1)=X, x(2)=Xdot, x(3)=theta, x(4)=thetadot
    X      = x(1);
    Xdot   = x(2);
    theta  = x(3);
    thetadot = x(4);

    %Den = M + m*(sin(theta))^2;
    Den = M + m*(sin(theta))^2;
    % Numerators (derived from solving the 2x2 linear system)
    %EOM not dependant on X.
    % Xddot = ( u - b*Xdot + m*l*thetadot^2*sin(theta) - m*g*sin(theta)*cos(theta) ) / Den;
    % 
    % thetaddot = ( (M + m)*g*sin(theta) + b*Xdot*cos(theta) ...
    %               - m*l*thetadot^2*sin(theta)*cos(theta) - u*cos(theta) ) ...
    %              / ( l * Den );
    % Xddot = ( u - b*Xdot + m*g*sin(theta)*cos(theta) + m*l*(thetadot^2)*sin(theta) ) / Den;
    % 
    % thetaddot = ( (M + m)*g*sin(theta) + cos(theta)*( u - b*Xdot + m*l*(thetadot^2)*sin(theta) ) ) ...
    %         / ( l * Den );
    Xddot = ( u - b*Xdot + m*l*thetadot^2*sin(theta) + m*g*sin(theta)*cos(theta) ) / Den;
     
    thetaddot = ( (M + m)*g*sin(theta) - b*Xdot*cos(theta) ...
                   + m*l*thetadot^2*sin(theta)*cos(theta) + u*cos(theta) ) ...
                  / ( l * Den );

    dx = [ Xdot; Xddot; thetadot; thetaddot ];
end
%%
A = [0 1 0 0 ; 0 -d/m m*g/M 0 ; 0 0 0 1; 0 -d/l*M (M+m)*g/(l*M) 0] %[output:32377b4c]
%%
B = [0 1/M 0 1/(M*l)]' %[output:7e1d6e29]
%%
R = 1e-3;
%%
Q = [0.1 0 0 0 ; 
    0 100 0 0;
    0 0 11 0;
    0 0 0 1000];
%%
K = lqr(A,B,Q,R) %[output:461c48aa]
%%
% Closed-loop system
Acl = A - B*K;
sys_cl = ss(Acl, [], eye(4), []);

% Simulate response
t_sim = 0:0.01:10;
[y, t] = initial(sys_cl, x0, t_sim);

% Plot
figure; %[output:61c3d42a]
plot(t, y); %[output:61c3d42a]
xlabel('Time (s)'); %[output:61c3d42a]
ylabel('States [x, xdot, theta, thetadot]'); %[output:61c3d42a]
legend('x (cart pos)', 'xdot', 'theta', 'thetadot'); %[output:61c3d42a]
title('Closed-Loop Response of Cart-Pendulum System with LQR'); %[output:61c3d42a]
grid on; %[output:61c3d42a]

% Eigenvalues
disp('Closed-loop eigenvalues:'); %[output:86768af9]
disp(eig(Acl)); %[output:4381f027]
%%
t_sim = 0:0.01:10;
%%
% Simulate the system response using the state-space representation
sys = ss(A, B, eye(4), 0);
[y, t] = lsim(sys, u*ones(size(t_sim)), t_sim, x0);
%%
% Plot the system response
figure; %[output:05b621b8]
plot(t, y); %[output:05b621b8]
xlabel('Time (s)'); %[output:05b621b8]
ylabel('System Response'); %[output:05b621b8]
title('Response of the Cart-Pendulum System'); %[output:05b621b8]
legend('x (cart pos)', 'xdot', 'theta', 'thetadot'); %[output:05b621b8]
grid on; %[output:05b621b8]
%%
[A,B,C,D] = linmod('model') %[output:7b10ff5c] %[output:83c02f17] %[output:0e5a19f7] %[output:56fc8239]
sys = ss(A, B, C, D);
y_inf = dcgain(sys)   % This gives steady-state value for a unit step input %[output:5dd7b08e]


